"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[55650],{27864:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var n=h(31085),s=h(71184);const i={sidebar_position:22,slug:"/bible/Luke/Luke_22",title:"Luke 22",hide_table_of_contents:!0},o="Luke",a={id:"bible/Luke/Luke 22",title:"Luke 22",description:"Chapter 22",source:"@site/docs/bible/Luke/Luke 22.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_22",permalink:"/docs/bible/Luke/Luke_22",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Luke/Luke 22.md",tags:[],version:"current",sidebarPosition:22,frontMatter:{sidebar_position:22,slug:"/bible/Luke/Luke_22",title:"Luke 22",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 21",permalink:"/docs/bible/Luke/Luke_21"},next:{title:"Luke 23",permalink:"/docs/bible/Luke/Luke_23"}},r={},d=[{value:"Chapter 22",id:"chapter-22",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-22",children:"Chapter 22"}),"\n",(0,n.jsx)(t.p,{children:"The treason of Judas.  The last supper.  The first part of the history of the passion."}),"\n",(0,n.jsx)(h,{verse:1,children:"Now the feast of unleavened bread, which is called the pasch, was at hand."}),"\n",(0,n.jsx)(h,{verse:2,children:"And the chief priests and the scribes sought how they might put Jesus to death: but they feared the people."}),"\n",(0,n.jsx)(h,{verse:3,children:"And Satan entered into Judas, who was surnamed Iscariot, one of the twelve."}),"\n",(0,n.jsx)(h,{verse:4,children:"And he went and discoursed with the chief priests and the magistrates, how he might betray him to them."}),"\n",(0,n.jsx)(h,{verse:5,children:"And they were glad and covenanted to give him money."}),"\n",(0,n.jsx)(h,{verse:6,children:"And he promised. And he sought opportunity to betray him in the absence of the multitude."}),"\n",(0,n.jsx)(h,{verse:7,children:"And the day of the unleavened bread came, on which it was necessary that the pasch should be killed."}),"\n",(0,n.jsx)(h,{verse:8,children:"And he sent Peter and John, saying: Go, and prepare for us the pasch, that we may eat."}),"\n",(0,n.jsx)(h,{verse:9,children:"But they said: Where wilt thou that we prepare?"}),"\n",(0,n.jsx)(h,{verse:10,children:"And he said to them: Behold, as you go into the city, there shall meet you a man carrying a pitcher of water: follow him into the house where he entereth in."}),"\n",(0,n.jsx)(h,{verse:11,children:"And you shall say to the goodman of the house: The master saith to thee: Where is the guest chamber, where I may eat the pasch with my disciples?"}),"\n",(0,n.jsx)(h,{verse:12,children:"And he will shew you a large dining room, furnished. And there prepare."}),"\n",(0,n.jsx)(h,{verse:13,children:"And they going, found as he had said to them and made ready the pasch."}),"\n",(0,n.jsx)(h,{verse:14,children:"And when the hour was come, he sat down: and the twelve apostles with him."}),"\n",(0,n.jsx)(h,{verse:15,children:"And he said to them: With desire I have desired to eat this pasch with you, before I suffer."}),"\n",(0,n.jsx)(h,{verse:16,children:"For I say to you that from this time I will not eat it, till it be fulfilled in the kingdom of God."}),"\n",(0,n.jsx)(h,{verse:17,children:"And having taken the chalice, he gave thanks and said: Take and divide it among you."}),"\n",(0,n.jsx)(h,{verse:18,children:"For I say to you that I will not drink of the fruit of the vine, till the kingdom of God come."}),"\n",(0,n.jsx)(h,{verse:19,children:"And taking bread, he gave thanks and brake and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Do this for a commemoration of me...This sacrifice and sacrament is to be continued in the church, to the end of the world, to shew forth the death of Christ, until he cometh. But this commemoration, or remembrance, is by no means inconsistent with the real presence of his body and blood, under these sacramental veils, which represent his death; on the contrary, it is the manner that he himself hath commanded, of commemorating and celebrating his death, by offering in sacrifice, and receiving in the sacrament, that body and blood by which we were redeemed."})}),"\n",(0,n.jsx)(h,{verse:20,children:"In like manner, the chalice also, after he had supped, saying: This is the chalice, the new testament in my blood, which shall be shed for you."}),"\n",(0,n.jsx)(h,{verse:21,children:"But yet behold: the hand of him that betrayeth me is with me on the table."}),"\n",(0,n.jsx)(h,{verse:22,children:"And the Son of man indeed goeth, according to that which is determined: but yet, woe to that man by whom he shall be betrayed."}),"\n",(0,n.jsx)(h,{verse:23,children:"And they began to inquire among themselves, which of them it was that should do this thing."}),"\n",(0,n.jsx)(h,{verse:24,children:"And there was also a strife amongst them, which of them should seem to be the greater."}),"\n",(0,n.jsx)(h,{verse:25,children:"And he said to them: The kings of the Gentiles lord it over them; and they that have power over them are called beneficent."}),"\n",(0,n.jsx)(h,{verse:26,children:"But you not so: but he that is the greater among you, let him become as the younger: and he that is the leader, as he that serveth."}),"\n",(0,n.jsx)(h,{verse:27,children:"For which is greater, he that sitteth at table or he that serveth? Is not he that sitteth at table? But I am in the midst of you, as he that serveth."}),"\n",(0,n.jsx)(h,{verse:28,children:"And you are they who have continued with me in my temptations:"}),"\n",(0,n.jsx)(h,{verse:29,children:"And I dispose to you, as my Father hath disposed to me, a kingdom;"}),"\n",(0,n.jsx)(h,{verse:30,children:"That you may eat and drink at my table, in my kingdom: and may sit upon thrones, judging the twelve tribes of Israel."}),"\n",(0,n.jsx)(h,{verse:31,children:"And the Lord said: Simon, Simon, behold Satan hath desired to have you, that he may sift you as wheat."}),"\n",(0,n.jsx)(h,{verse:32,children:"But I have prayed for thee, that thy faith fail not: and thou, being once converted, confirm thy brethren."}),"\n",(0,n.jsx)(h,{verse:33,children:"Who said to him: Lord, I am ready to go with thee, both into prison and to death."}),"\n",(0,n.jsx)(h,{verse:34,children:"And he said: I say to thee, Peter, the cock shall not crow this day, till thou thrice deniest that thou knowest me. And he said to them:"}),"\n",(0,n.jsx)(h,{verse:35,children:"When I sent you without purse and scrip and shoes, did you want anything?"}),"\n",(0,n.jsx)(h,{verse:36,children:"But they said: Nothing. Then said he unto them: But now he that hath a purse, let him take it, and likewise a scrip: and he that hath not, let him sell his coat and buy a sword."}),"\n",(0,n.jsx)(h,{verse:37,children:"For I say to you that this that is written must yet be fulfilled in me. And with the wicked was he reckoned. For the things concerning me have an end."}),"\n",(0,n.jsx)(h,{verse:38,children:"But they said: Lord, behold, here are two swords. And he said to them: It is enough."}),"\n",(0,n.jsx)(h,{verse:39,children:"And going out, he went, according to his custom, to the Mount of Olives. And his disciples also followed him."}),"\n",(0,n.jsx)(h,{verse:40,children:"And when he was come to the place, he said to them: Pray, lest ye enter into temptation."}),"\n",(0,n.jsx)(h,{verse:41,children:"And he was withdrawn away from them a stone's cast. And kneeling down, he prayed."}),"\n",(0,n.jsx)(h,{verse:42,children:"Saying: Father, if thou wilt, remove this chalice from me: but yet not my will, but thine be done."}),"\n",(0,n.jsx)(h,{verse:43,children:"And there appeared to him an angel from heaven, strengthening him. And being in an agony, he prayed the longer."}),"\n",(0,n.jsx)(h,{verse:44,children:"And his sweat became as drops of blood, trickling down upon the ground."}),"\n",(0,n.jsx)(h,{verse:45,children:"And when he rose up from prayer and was come to the disciples, he found them sleeping for sorrow."}),"\n",(0,n.jsx)(h,{verse:46,children:"And he said to them: Why sleep you? Arise: pray: lest you enter into temptation."}),"\n",(0,n.jsx)(h,{verse:47,children:"As he was yet speaking, behold a multitude; and he that was called Judas, one of the twelve, went before them and drew near to Jesus, for to kiss him."}),"\n",(0,n.jsx)(h,{verse:48,children:"And Jesus said to him: Judas, dost thou betray the Son of man with a kiss?"}),"\n",(0,n.jsx)(h,{verse:49,children:"And they that were about him, seeing what would follow, said to him: Lord, shall we strike with the sword?"}),"\n",(0,n.jsx)(h,{verse:50,children:"And one of them struck the servant of the high priest and cut off his right ear."}),"\n",(0,n.jsx)(h,{verse:51,children:"But Jesus answering, said: Suffer ye thus far. And when he had touched his ear, he healed him."}),"\n",(0,n.jsx)(h,{verse:52,children:"And Jesus said to the chief priests and magistrates of the temple and the ancients, that were come unto him: Are ye come out, as it were against a thief, with swords and clubs?"}),"\n",(0,n.jsx)(h,{verse:53,children:"When I was daily with you in the temple, you did not stretch forth your hands against me: but this is your hour and the power of darkness."}),"\n",(0,n.jsx)(h,{verse:54,children:"And apprehending him, they led him to the high priest's house. But Peter followed afar off."}),"\n",(0,n.jsx)(h,{verse:55,children:"And when they had kindled a fire in the midst of the hall and were sitting about it, Peter was in the midst of them."}),"\n",(0,n.jsx)(h,{verse:56,children:"Whom when a certain servant maid had seen sitting at the light and had earnestly beheld him, she said: This man also was with him."}),"\n",(0,n.jsx)(h,{verse:57,children:"But he denied him, saying: Woman, I know him not."}),"\n",(0,n.jsx)(h,{verse:58,children:"And after a little while, another seeing him, said: Thou also art one of them. But Peter said: O man, I am not."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Another, etc...Observe here, in order to reconcile the four Evangelists, that divers persons concurred in charging Peter with being Christ's disciple; till at length they brought him to deny him thrice. 1. The porteress that let him in, and afterwards seeing him at the fire, first put the question to him; and then positively affirmed that he was with Christ. 2. Another maid accused him to the standers by; and gave occasion to the man here mentioned to renew the charge against him, which caused the second denial. 3. Others of the company took notice of his being a Galilean; and were seconded by the kinsman of Malchus, who affirmed he had seen him in the garden. And this drew on the third denial."})}),"\n",(0,n.jsx)(h,{verse:59,children:"And after the space, as it were of one hour, another certain man affirmed, saying: Of a truth, this man was also with him: for he is also a Galilean."}),"\n",(0,n.jsx)(h,{verse:60,children:"And Peter said: Man, I know not what thou sayest. And immediately, as he was yet speaking, the cock crew."}),"\n",(0,n.jsx)(h,{verse:61,children:"And the Lord turning looked on Peter. And Peter remembered the word of the Lord, as he had said: Before the cock crow, thou shalt deny thrice."}),"\n",(0,n.jsx)(h,{verse:62,children:"And Peter going out, wept bitterly."}),"\n",(0,n.jsx)(h,{verse:63,children:"And the men that held him mocked him and struck him."}),"\n",(0,n.jsx)(h,{verse:64,children:"And they blindfolded him and smote his face. And they asked him saying: Prophesy: Who is it that struck thee?"}),"\n",(0,n.jsx)(h,{verse:65,children:"And blaspheming, many other things they said against him."}),"\n",(0,n.jsx)(h,{verse:66,children:"And as soon as it was day, the ancients of the people and the chief priests and scribes came together. And they brought him into their council saying: If thou be the Christ, tell us."}),"\n",(0,n.jsx)(h,{verse:67,children:"And he saith to them: If I shall tell you, you will not believe me."}),"\n",(0,n.jsx)(h,{verse:68,children:"And if I shall also ask you, you will not answer me, nor let me go."}),"\n",(0,n.jsx)(h,{verse:69,children:"But hereafter the Son of man shall be sitting on the right hand of the power of God."}),"\n",(0,n.jsx)(h,{verse:70,children:"Then said they all: Art thou then the Son of God? Who said: You say that I am."}),"\n",(0,n.jsx)(h,{verse:71,children:"And they said: What need we any further testimony? For we ourselves have heard it from his own mouth."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>o,x:()=>a});var n=h(14041);const s={},i=n.createContext(s);function o(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);